import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
rows = None
for rec in records:
    if rec.get('source'):
        continue
    vals = rec.get('values', {})
    if 'rows' in vals:
        rows = vals['rows']
        break
if rows is None:
    raise ValueError('No product data found in LEGACY_RECORDS.')
products = []
revenue = {}
demand = {}
inventory = {}
for row in rows:
    pname = row['Full_Product_Name']
    products.append(pname)
    try:
        revenue[pname] = float(row['Revenue'])
        demand[pname] = int(row['Demand'])
        inventory[pname] = int(row['Initial Inventory'])
    except Exception as e:
        raise ValueError(f'Invalid data for product {pname}: {e}')
for pname in products:
    if pname not in revenue or pname not in demand or pname not in inventory:
        raise ValueError(f'Missing data for product {pname}')
upper_bound = {p: min(demand[p], inventory[p]) for p in products}
m = gp.Model('Dairy_Fulfillment')
x = m.addVars(products, lb=0, ub=upper_bound, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[p] * x[p] for p in products)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')